  FUNCTION ONUMM6N4_SQRT(X) RESULT(RES)
      IMPLICIT NONE
      TYPE(ONUMM6N4), INTENT(IN) :: X
      TYPE(ONUMM6N4) :: RES

      RES = X**0.5_DP

  END FUNCTION ONUMM6N4_SQRT

  FUNCTION ONUMM6N4_MAX(X1,X2) RESULT(RES)
      IMPLICIT NONE
      TYPE(ONUMM6N4), INTENT(IN) :: X1, X2
                                                
      TYPE(ONUMM6N4) :: RES
      RES = X1
      IF (X2>RES) RES = X2  

  END FUNCTION ONUMM6N4_MAX

  FUNCTION ONUMM6N4_MIN(X1,X2) RESULT(RES)
      IMPLICIT NONE
      TYPE(ONUMM6N4), INTENT(IN) :: X1, X2
                                                
      TYPE(ONUMM6N4) :: RES
      RES = X1
      IF (X2<RES) RES = X2

  END FUNCTION ONUMM6N4_MIN

  FUNCTION ONUMM6N4_MAXLOC_R1(ARRAY, MASK, BACK) RESULT(RES)
      IMPLICIT NONE
      TYPE(ONUMM6N4), INTENT(IN) :: ARRAY(:)
      LOGICAL, INTENT(IN), OPTIONAL :: MASK(SIZE(ARRAY,1))
      LOGICAL, INTENT(IN), OPTIONAL :: BACK  ! Search from the back
      
      INTEGER :: RES( 1)
      
      LOGICAL :: MASK_DEF(SIZE(ARRAY,1))
      LOGICAL :: BACK_DEF
      
      ! Assign defaults.
      MASK_DEF = .true.
      BACK_DEF = .false.
      
      IF (PRESENT(MASK)) MASK_DEF = MASK
      IF (PRESENT(BACK)) BACK_DEF = BACK

      RES = MAXLOC(ARRAY%R, MASK = MASK_DEF)

