  ELEMENTAL FUNCTION ONUMM6N4_TAN(X) RESULT(RES)

    TYPE(ONUMM6N4), INTENT(IN) :: X
    REAL(DP) :: DER0,DER1,DER2,DER3,DER4
    TYPE(ONUMM6N4) :: RES
    
    DER0 = TAN(X%R)
    DER1 = TAN(X%R)**2 + 1
    DER2 = 2*(TAN(X%R)**2 + 1)*TAN(X%R)
    DER3 = 2*(TAN(X%R)**2 + 1)*(3*TAN(X%R)**2 + 1)
    DER4 = 8*(TAN(X%R)**2 + 1)*(3*TAN(X%R)**2 + 2)*TAN(X%R)

    RES = FEVAL(X,DER0,DER1,DER2,DER3,DER4)

  END FUNCTION ONUMM6N4_TAN

  ELEMENTAL FUNCTION ONUMM6N4_COS(X) RESULT(RES)

    TYPE(ONUMM6N4), INTENT(IN) :: X
    REAL(DP) :: DER0,DER1,DER2,DER3,DER4
    TYPE(ONUMM6N4) :: RES
    
    DER0 = COS(X%R)
    DER1 = -SIN(X%R)
    DER2 = -COS(X%R)
    DER3 = SIN(X%R)
    DER4 = COS(X%R)

    RES = FEVAL(X,DER0,DER1,DER2,DER3,DER4)

  END FUNCTION ONUMM6N4_COS

  ELEMENTAL FUNCTION ONUMM6N4_SIN(X) RESULT(RES)

    TYPE(ONUMM6N4), INTENT(IN) :: X
    REAL(DP) :: DER0,DER1,DER2,DER3,DER4
    TYPE(ONUMM6N4) :: RES
    
    DER0 = SIN(X%R)
    DER1 = COS(X%R)
    DER2 = -SIN(X%R)
    DER3 = -COS(X%R)
    DER4 = SIN(X%R)

    RES = FEVAL(X,DER0,DER1,DER2,DER3,DER4)

  END FUNCTION ONUMM6N4_SIN

  ELEMENTAL FUNCTION ONUMM6N4_ATAN(X) RESULT(RES)

    TYPE(ONUMM6N4), INTENT(IN) :: X
    REAL(DP) :: DER0,DER1,DER2,DER3,DER4
    TYPE(ONUMM6N4) :: RES
    
    DER0 = ATAN(X%R)
    DER1 = 1D0/(X%R**2 + 1)
    DER2 = -2*X%R/(X%R**2 + 1)**2
    DER3 = 2*(4*X%R**2/(X%R**2 + 1) - 1)/(X%R**2 + 1)**2
    DER4 = 24*X%R*(-2*X%R**2/(X%R**2 + 1) + 1)/(X%R**2 + 1)**3

    RES = FEVAL(X,DER0,DER1,DER2,DER3,DER4)

  END FUNCTION ONUMM6N4_ATAN

  ELEMENTAL FUNCTION ONUMM6N4_ACOS(X) RESULT(RES)

    TYPE(ONUMM6N4), INTENT(IN) :: X
    REAL(DP) :: DER0,DER1,DER2,DER3,DER4
    TYPE(ONUMM6N4) :: RES
    
    DER0 = ACOS(X%R)
    DER1 = -1/SQRT(1 - X%R**2)
    DER2 = -X%R/(1 - X%R**2)**(3.0D0/2.0D0)
    DER3 = -(3*X%R**2/(1 - X%R**2) + 1)/(1 - X%R**2)**(3.0D0/2.0D0)
    DER4 = -3*X%R*(5*X%R**2/(1 - X%R**2) + 3)/(1 - X%R**2)**(5.0D0/2.0D0)

    RES = FEVAL(X,DER0,DER1,DER2,DER3,DER4)

  END FUNCTION ONUMM6N4_ACOS

  ELEMENTAL FUNCTION ONUMM6N4_ASIN(X) RESULT(RES)

    TYPE(ONUMM6N4), INTENT(IN) :: X
    REAL(DP) :: DER0,DER1,DER2,DER3,DER4
    TYPE(ONUMM6N4) :: RES
    
    DER0 = ASIN(X%R)
    DER1 = 1/SQRT(1 - X%R**2)
    DER2 = X%R/(1 - X%R**2)**(3.0D0/2.0D0)
    DER3 = (3*X%R**2/(1 - X%R**2) + 1)/(1 - X%R**2)**(3.0D0/2.0D0)
    DER4 = 3*X%R*(5*X%R**2/(1 - X%R**2) + 3)/(1 - X%R**2)**(5.0D0/2.0D0)

    RES = FEVAL(X,DER0,DER1,DER2,DER3,DER4)

  END FUNCTION ONUMM6N4_ASIN

  ELEMENTAL FUNCTION ONUMM6N4_TANH(X) RESULT(RES)

    TYPE(ONUMM6N4), INTENT(IN) :: X
    REAL(DP) :: DER0,DER1,DER2,DER3,DER4
    TYPE(ONUMM6N4) :: RES
    
    DER0 = TANH(X%R)
    DER1 = 1 - TANH(X%R)**2
    DER2 = 2*(TANH(X%R)**2 - 1)*TANH(X%R)
    DER3 = -2*(TANH(X%R)**2 - 1)*(3*TANH(X%R)**2 - 1)
    DER4 = 8*(TANH(X%R)**2 - 1)*(3*TANH(X%R)**2 - 2)*TANH(X%R)

    RES = FEVAL(X,DER0,DER1,DER2,DER3,DER4)

  END FUNCTION ONUMM6N4_TANH

  ELEMENTAL FUNCTION ONUMM6N4_COSH(X) RESULT(RES)

    TYPE(ONUMM6N4), INTENT(IN) :: X
    REAL(DP) :: DER0,DER1,DER2,DER3,DER4
    TYPE(ONUMM6N4) :: RES
    
    DER0 = COSH(X%R)
    DER1 = SINH(X%R)
    DER2 = COSH(X%R)
    DER3 = SINH(X%R)
    DER4 = COSH(X%R)

    RES = FEVAL(X,DER0,DER1,DER2,DER3,DER4)

  END FUNCTION ONUMM6N4_COSH

  ELEMENTAL FUNCTION ONUMM6N4_SINH(X) RESULT(RES)

    TYPE(ONUMM6N4), INTENT(IN) :: X
    REAL(DP) :: DER0,DER1,DER2,DER3,DER4
    TYPE(ONUMM6N4) :: RES
    
    DER0 = SINH(X%R)
    DER1 = COSH(X%R)
    DER2 = SINH(X%R)
    DER3 = COSH(X%R)
    DER4 = SINH(X%R)

    RES = FEVAL(X,DER0,DER1,DER2,DER3,DER4)

  END FUNCTION ONUMM6N4_SINH

  ELEMENTAL FUNCTION ONUMM6N4_EXP(X) RESULT(RES)

    TYPE(ONUMM6N4), INTENT(IN) :: X
    REAL(DP) :: DER0,DER1,DER2,DER3,DER4
    TYPE(ONUMM6N4) :: RES
    
    DER0 = EXP(X%R)
    DER1 = EXP(X%R)
    DER2 = EXP(X%R)
    DER3 = EXP(X%R)
    DER4 = EXP(X%R)

    RES = FEVAL(X,DER0,DER1,DER2,DER3,DER4)

  END FUNCTION ONUMM6N4_EXP

  ELEMENTAL FUNCTION ONUMM6N4_LOG(X) RESULT(RES)

    TYPE(ONUMM6N4), INTENT(IN) :: X
    REAL(DP) :: DER0,DER1,DER2,DER3,DER4
    TYPE(ONUMM6N4) :: RES
    
    DER0 = LOG(X%R)
    DER1 = 1D0/X%R
    DER2 = -1/X%R**2
    DER3 = 2/X%R**3
    DER4 = -6/X%R**4

    RES = FEVAL(X,DER0,DER1,DER2,DER3,DER4)

  END FUNCTION ONUMM6N4_LOG

  ELEMENTAL FUNCTION ONUMM6N4_POW_OR(X,E) RESULT(RES)

    TYPE(ONUMM6N4), INTENT(IN) :: X
    REAL(DP), INTENT(IN) :: E
    REAL(DP) :: DER0,DER1,DER2,DER3,DER4
    TYPE(ONUMM6N4) :: RES
    
    DER0=0.0d0
    DER1=0.0d0
    DER2=0.0d0
    DER3=0.0d0
    DER4=0.0d0
    
    DER0 = X%R**E
    IF ((E-0)/=0.0d0) THEN
      DER1 = E*X%R**(E - 1)
      IF ((E-1)/=0.0d0) THEN
        DER2 = E*X%R**(E - 2)*(E - 1)
        IF ((E-2)/=0.0d0) THEN
          DER3 = E*X%R**(E - 3)*(E**2 - 3*E + 2)
          IF ((E-3)/=0.0d0) THEN
            DER4 = E*X%R**(E - 4)*(E**3 - 6*E**2 + 11*E - 6)
          END IF
        END IF
      END IF
    END IF

    RES = FEVAL(X,DER0,DER1,DER2,DER3,DER4)

  END FUNCTION ONUMM6N4_POW_OR

  ELEMENTAL FUNCTION ONUMM6N4_POW_RO(E,X) RESULT(RES)

    TYPE(ONUMM6N4), INTENT(IN) :: X
    REAL(DP), INTENT(IN) :: E
    REAL(DP) :: DER0,DER1,DER2,DER3,DER4
    TYPE(ONUMM6N4) :: RES
    
    
    DER0 = E**X%R
    DER1 = E**X%R*LOG(E)
    DER2 = E**X%R*LOG(E)**2
    DER3 = E**X%R*LOG(E)**3
    DER4 = E**X%R*LOG(E)**4

    RES = FEVAL(X,DER0,DER1,DER2,DER3,DER4)

  END FUNCTION ONUMM6N4_POW_RO

  ELEMENTAL FUNCTION ONUMM6N4_POW_I8O(E,X) RESULT(RES)

    TYPE(ONUMM6N4), INTENT(IN) :: X
    INTEGER(8), INTENT(IN) :: E
    TYPE(ONUMM6N4) :: RES
    
    RES = ONUMM6N4_POW_RO(REAL(E,8),X)
    
  END FUNCTION 

  ELEMENTAL FUNCTION ONUMM6N4_POW_I4O(E,X) RESULT(RES)

    TYPE(ONUMM6N4), INTENT(IN) :: X
    INTEGER(4), INTENT(IN) :: E
    TYPE(ONUMM6N4) :: RES
    
    RES = ONUMM6N4_POW_RO(REAL(E,8),X)
    
  END FUNCTION 

  ELEMENTAL FUNCTION ONUMM6N4_POW_OI8(X,E) RESULT(RES)

    TYPE(ONUMM6N4), INTENT(IN) :: X
    INTEGER(8), INTENT(IN) :: E
    TYPE(ONUMM6N4) :: RES
    
    RES = ONUMM6N4_POW_OR(X,REAL(E,8))
    
  END FUNCTION 

  ELEMENTAL FUNCTION ONUMM6N4_POW_OI4(X,E) RESULT(RES)

    TYPE(ONUMM6N4), INTENT(IN) :: X
    INTEGER(4), INTENT(IN) :: E
    TYPE(ONUMM6N4) :: RES
    
    RES = ONUMM6N4_POW_OR(X,REAL(E,8))
    
  END FUNCTION 

  ELEMENTAL FUNCTION ONUMM6N4_F2EVAL(X,Y,DER0_0,DER1_0,DER1_1, &
                               DER2_0,DER2_1,DER2_2,DER3_0, &
                               DER3_1,DER3_2,DER3_3,DER4_0, &
                               DER4_1,DER4_2,DER4_3,DER4_4)&
    RESULT(RES)
    IMPLICIT NONE
    !  Definitions
    REAL(DP) :: COEF
    TYPE(ONUMM6N4), INTENT(IN)  :: X,Y
    REAL(DP), INTENT(IN)  :: DER0_0,DER1_0,DER1_1, &
                             DER2_0,DER2_1,DER2_2,DER3_0, &
                             DER3_1,DER3_2,DER3_3,DER4_0, &
                             DER4_1,DER4_2,DER4_3,DER4_4
    TYPE(ONUMM6N4) :: RES
    TYPE(ONUMM6N4) :: DX, DY

    COEF   = 0.0_DP
    DX     = X
    DY     = Y

    !  Set real part of deltas zero.
    DX%R = 0.0_dp
    DY%R = 0.0_dp

    ! Set real part
    RES = DER0_0

    ! Set order 1
    COEF = DER1_0 / 1.0_DP
    RES = RES + COEF*DX

    COEF = DER1_1 / 1.0_DP
    RES = RES + COEF*DY

    

    ! Set order 2
    COEF = DER2_0 / 1.0_DP
    RES = RES + COEF*DX*DX

    COEF = DER2_1 / 1.0_DP
    RES = RES + COEF*DX*DY

    COEF = DER2_2 / 1.0_DP
    RES = RES + COEF*DY*DY

    

    ! Set order 3
    COEF = DER3_0 / 1.0_DP
    RES = RES + COEF*DX*DX*DX

    COEF = DER3_1 / 1.0_DP
    RES = RES + COEF*DX*DX*DY

    COEF = DER3_2 / 1.0_DP
    RES = RES + COEF*DX*DY*DY

    COEF = DER3_3 / 1.0_DP
    RES = RES + COEF*DY*DY*DY

    

    ! Set order 4
    COEF = DER4_0 / 1.0_DP
    RES = RES + COEF*DX*DX*DX*DX

    COEF = DER4_1 / 1.0_DP
    RES = RES + COEF*DX*DX*DX*DY

    COEF = DER4_2 / 1.0_DP
    RES = RES + COEF*DX*DX*DY*DY

    COEF = DER4_3 / 1.0_DP
    RES = RES + COEF*DX*DY*DY*DY

    COEF = DER4_4 / 1.0_DP
    RES = RES + COEF*DY*DY*DY*DY

    

  END FUNCTION ONUMM6N4_F2EVAL


  ELEMENTAL FUNCTION ONUMM6N4_POW_OO(X,Y) RESULT(RES)

    TYPE(ONUMM6N4), INTENT(IN) :: X, Y
    REAL(DP) :: DER0_0,DER1_0,DER1_1,DER2_0,DER2_1,DER2_2,DER3_0,DER3_1,DER3_2,DER3_3,DER4_0,DER4_1,DER4_2,DER4_3,DER4_4
    TYPE(ONUMM6N4) :: RES
    
    DER0_0 = X%R**Y%R
    DER1_0 = X%R**Y%R*Y%R/X%R
    DER1_1 = X%R**Y%R*LOG(X%R)
    DER2_0 = X%R**Y%R*Y%R*(Y%R - 1)/X%R**2
    DER2_1 = X%R**Y%R*(Y%R*LOG(X%R) + 1)/X%R
    DER2_2 = X%R**Y%R*LOG(X%R)**2
    DER3_0 = X%R**Y%R*Y%R*(Y%R**2 - 3*Y%R + 2)/X%R**3
    DER3_1 = X%R**Y%R*(Y%R**2*LOG(X%R) - Y%R*LOG(X%R) + 2*Y%R - 1)/X%R**2
    DER3_2 = X%R**Y%R*(Y%R*LOG(X%R) + 2)*LOG(X%R)/X%R
    DER3_3 = X%R**Y%R*LOG(X%R)**3
    DER4_0 = X%R**Y%R*Y%R*(Y%R**3 - 6*Y%R**2 + 11*Y%R - 6)/X%R**4
    DER4_1 = X%R**Y%R*(Y%R**3*LOG(X%R) - 3*Y%R**2*LOG(X%R) + 3*Y%R**2 + 2*Y% &
      R*LOG(X%R) - 6*Y%R + 2)/X%R**3
    DER4_2 = X%R**Y%R*(Y%R**2*LOG(X%R)**2 - Y%R*LOG(X%R)**2 + 4*Y%R*LOG(X%R &
      ) - 2*LOG(X%R) + 2)/X%R**2
    DER4_3 = X%R**Y%R*(Y%R*LOG(X%R) + 3)*LOG(X%R)**2/X%R
    DER4_4 = X%R**Y%R*LOG(X%R)**4

    RES = F2EVAL(X,Y,DER0_0,DER1_0,DER1_1,DER2_0,DER2_1,DER2_2,DER3_0,DER3_1,DER3_2,DER3_3,DER4_0,DER4_1,DER4_2,DER4_3,DER4_4)

  END FUNCTION ONUMM6N4_POW_OO


  FUNCTION ONUMM6N4_INV2X2(A,det)&
    RESULT(RES)
    IMPLICIT NONE
    TYPE(ONUMM6N4) , INTENT(IN) :: A(2,2) 
    TYPE(ONUMM6N4) , INTENT(IN), OPTIONAL :: det
    REAL(DP) :: detCalc
    TYPE(ONUMM6N4) :: RES(SIZE(A,1),SIZE(A,2)) 

    IF (PRESENT(det)) THEN
      detCalc=det%R
    ELSE
      detCalc=det2x2(A%R)
    END IF

    ! Get real part 
    RES%R=INV2X2(A%R,detCalc)

    ! Order 1
    RES%E1=-MATMUL(RES%R,(MATMUL(A%E1,RES%R)))
    RES%E2=-MATMUL(RES%R,(MATMUL(A%E2,RES%R)))
    RES%E3=-MATMUL(RES%R,(MATMUL(A%E3,RES%R)))
    RES%E4=-MATMUL(RES%R,(MATMUL(A%E4,RES%R)))
    RES%E5=-MATMUL(RES%R,(MATMUL(A%E5,RES%R)))
    RES%E6=-MATMUL(RES%R,(MATMUL(A%E6,RES%R)))

    ! Order 2
    RES%E11=-MATMUL(RES%R,(MATMUL(A%E11,RES%R)+MATMUL(A%E1,RES%E1)))
    RES%E12=-MATMUL(RES%R,(MATMUL(A%E12,RES%R)+MATMUL(A%E1,RES%E2)+&
           MATMUL(A%E2,RES%E1)))
    RES%E22=-MATMUL(RES%R,(MATMUL(A%E22,RES%R)+MATMUL(A%E2,RES%E2)))
    RES%E13=-MATMUL(RES%R,(MATMUL(A%E13,RES%R)+MATMUL(A%E1,RES%E3)+&
           MATMUL(A%E3,RES%E1)))
    RES%E23=-MATMUL(RES%R,(MATMUL(A%E23,RES%R)+MATMUL(A%E2,RES%E3)+&
           MATMUL(A%E3,RES%E2)))
    RES%E33=-MATMUL(RES%R,(MATMUL(A%E33,RES%R)+MATMUL(A%E3,RES%E3)))
    RES%E14=-MATMUL(RES%R,(MATMUL(A%E14,RES%R)+MATMUL(A%E1,RES%E4)+&
           MATMUL(A%E4,RES%E1)))
    RES%E24=-MATMUL(RES%R,(MATMUL(A%E24,RES%R)+MATMUL(A%E2,RES%E4)+&
           MATMUL(A%E4,RES%E2)))
    RES%E34=-MATMUL(RES%R,(MATMUL(A%E34,RES%R)+MATMUL(A%E3,RES%E4)+&
           MATMUL(A%E4,RES%E3)))
    RES%E44=-MATMUL(RES%R,(MATMUL(A%E44,RES%R)+MATMUL(A%E4,RES%E4)))
    RES%E15=-MATMUL(RES%R,(MATMUL(A%E15,RES%R)+MATMUL(A%E1,RES%E5)+&
           MATMUL(A%E5,RES%E1)))
    RES%E25=-MATMUL(RES%R,(MATMUL(A%E25,RES%R)+MATMUL(A%E2,RES%E5)+&
           MATMUL(A%E5,RES%E2)))
    RES%E35=-MATMUL(RES%R,(MATMUL(A%E35,RES%R)+MATMUL(A%E3,RES%E5)+&
           MATMUL(A%E5,RES%E3)))
    RES%E45=-MATMUL(RES%R,(MATMUL(A%E45,RES%R)+MATMUL(A%E4,RES%E5)+&
           MATMUL(A%E5,RES%E4)))
    RES%E55=-MATMUL(RES%R,(MATMUL(A%E55,RES%R)+MATMUL(A%E5,RES%E5)))
    RES%E16=-MATMUL(RES%R,(MATMUL(A%E16,RES%R)+MATMUL(A%E1,RES%E6)+&
           MATMUL(A%E6,RES%E1)))
    RES%E26=-MATMUL(RES%R,(MATMUL(A%E26,RES%R)+MATMUL(A%E2,RES%E6)+&
           MATMUL(A%E6,RES%E2)))
    RES%E36=-MATMUL(RES%R,(MATMUL(A%E36,RES%R)+MATMUL(A%E3,RES%E6)+&
           MATMUL(A%E6,RES%E3)))
    RES%E46=-MATMUL(RES%R,(MATMUL(A%E46,RES%R)+MATMUL(A%E4,RES%E6)+&
           MATMUL(A%E6,RES%E4)))
    RES%E56=-MATMUL(RES%R,(MATMUL(A%E56,RES%R)+MATMUL(A%E5,RES%E6)+&
           MATMUL(A%E6,RES%E5)))
    RES%E66=-MATMUL(RES%R,(MATMUL(A%E66,RES%R)+MATMUL(A%E6,RES%E6)))

    ! Order 3
    RES%E111=-MATMUL(RES%R,(MATMUL(A%E111,RES%R)+MATMUL(A%E1,RES%E11)+&
            MATMUL(A%E11,RES%E1)))
    RES%E112=-MATMUL(RES%R,(MATMUL(A%E112,RES%R)+MATMUL(A%E1,RES%E12)+&
            MATMUL(A%E12,RES%E1)+MATMUL(A%E2,RES%E11)+MATMUL(A%E11,RES%E2)))
    RES%E122=-MATMUL(RES%R,(MATMUL(A%E122,RES%R)+MATMUL(A%E1,RES%E22)+&
            MATMUL(A%E22,RES%E1)+MATMUL(A%E2,RES%E12)+MATMUL(A%E12,RES%E2)))
    RES%E222=-MATMUL(RES%R,(MATMUL(A%E222,RES%R)+MATMUL(A%E2,RES%E22)+&
            MATMUL(A%E22,RES%E2)))
    RES%E113=-MATMUL(RES%R,(MATMUL(A%E113,RES%R)+MATMUL(A%E1,RES%E13)+&
            MATMUL(A%E13,RES%E1)+MATMUL(A%E3,RES%E11)+MATMUL(A%E11,RES%E3)))
    RES%E123=-MATMUL(RES%R,(MATMUL(A%E123,RES%R)+MATMUL(A%E1,RES%E23)+&
            MATMUL(A%E23,RES%E1)+MATMUL(A%E2,RES%E13)+MATMUL(A%E13,RES%E2)+&
            MATMUL(A%E3,RES%E12)+MATMUL(A%E12,RES%E3)))
    RES%E133=-MATMUL(RES%R,(MATMUL(A%E133,RES%R)+MATMUL(A%E1,RES%E33)+&
            MATMUL(A%E33,RES%E1)+MATMUL(A%E3,RES%E13)+MATMUL(A%E13,RES%E3)))
    RES%E223=-MATMUL(RES%R,(MATMUL(A%E223,RES%R)+MATMUL(A%E2,RES%E23)+&
            MATMUL(A%E23,RES%E2)+MATMUL(A%E3,RES%E22)+MATMUL(A%E22,RES%E3)))
    RES%E233=-MATMUL(RES%R,(MATMUL(A%E233,RES%R)+MATMUL(A%E2,RES%E33)+&
            MATMUL(A%E33,RES%E2)+MATMUL(A%E3,RES%E23)+MATMUL(A%E23,RES%E3)))
    RES%E333=-MATMUL(RES%R,(MATMUL(A%E333,RES%R)+MATMUL(A%E3,RES%E33)+&
