! ===== j2_props_oti.f =====
! ============================================================
!  Small-strain 3D J2 plasticity with linear isotropic hardening.
!  NTENS = 6 (Voigt engineering shear on off-diagonals).
!  Parameters (from PROPS):
!     PROPS(1) = E     Young's modulus
!     PROPS(2) = XNU   Poisson's ratio
!     PROPS(3) = SIGY0 Initial yield stress
!     PROPS(4) = H     Linear isotropic hardening modulus
!  State variables:
!     STATEV(1) = EQPLAS  accumulated equivalent plastic strain
!
!  Radial-return integration (Simo & Hughes ch. 3): computes the
!  elastic trial stress, tests f=q-sigma_y, and if positive updates
!  stress via s_new = s_trial * (1 - 3*mu*dgamma/q_trial), then
!  recovers dgamma = (q_trial - sigma_y)/(3*mu + H). The consistent
!  tangent is emitted for Abaqus.
! ============================================================
      SUBROUTINE UMAT(STRESS,STATEV,DDSDDE,SSE,SPD,SCD, &
     & RPL,DDSDDT,DRPLDE,DRPLDT, &
     & STRAN,DSTRAN,TIME,DTIME,TEMP,DTEMP,PREDEF,DPRED,CMNAME, &
     & NDI,NSHR,NTENS,NSTATV,PROPS,NPROPS,COORDS,DROT,PNEWDT, &
     & CELENT,DFGRD0,DFGRD1,NOEL,NPT,LAYER,KSPT,KSTEP,KINC)
      USE otim6n4, OTI_MODULE_DP => DP, OTI_E1 => E1, OTI_E2 => E2, &
     & OTI_E3 => E3, OTI_E4 => E4, OTI_E5 => E5, OTI_E6 => E6
!
      INCLUDE 'ABA_PARAM.INC'
!
      CHARACTER*80 CMNAME
      DIMENSION STRESS(NTENS),STATEV(NSTATV), &
     & DDSDDE(NTENS,NTENS),DDSDDT(NTENS),DRPLDE(NTENS), &
     & STRAN(NTENS),DSTRAN(NTENS),TIME(2),PREDEF(1),DPRED(1), &
     & PROPS(NPROPS),COORDS(3),DROT(3,3),DFGRD0(3,3),DFGRD1(3,3)
!
      PARAMETER (ZERO = 0.0D0, ONE = 1.0D0, TWO = 2.0D0, &
     & THREE = 3.0D0, ONE_HALF = 0.5D0, &
     & ONE_THIRD = 0.333333333333333333D0, &
     & TWO_THIRDS = 0.666666666666666667D0, &
     & THREE_HALVES = 1.5D0)
!
      DIMENSION STRESS_TRIAL(6), DEV_TRIAL(6)
      INTEGER I, J
!
!     Material parameters from PROPS.
      INTEGER :: OTI_I, OTI_J, OTI_HI, OTI_HJ, OTI_HK
      TYPE(ONUMM6N4) :: OTI_HX, OTI_HY, OTI_HTR
      INTEGER :: IOTIHJ, IOTILN
      CHARACTER(256) :: OTI_OUTDIR
      TYPE(ONUMM6N4) :: DEV_TRIAL_OTI(6)
      TYPE(ONUMM6N4) :: DGAMMA_OTI
      TYPE(ONUMM6N4) :: DSTRAN_OTI(NTENS)
      TYPE(ONUMM6N4) :: EQPLAS_N_OTI
      TYPE(ONUMM6N4) :: PHI_OTI
      TYPE(ONUMM6N4) :: PTRIAL_OTI
      TYPE(ONUMM6N4) :: Q_TRIAL_OTI
      TYPE(ONUMM6N4) :: SCALE_OTI
      TYPE(ONUMM6N4) :: SIGMA_Y_OTI
      TYPE(ONUMM6N4) :: STATEV_OTI(NSTATV)
      TYPE(ONUMM6N4) :: STRESS_OTI(NTENS)
      TYPE(ONUMM6N4) :: STRESS_TRIAL_OTI(6)
      E     = PROPS(1)
      XNU   = PROPS(2)
      SIGY0 = PROPS(3)
      H     = PROPS(4)
      ELAM  = E * XNU / ((ONE + XNU) * (ONE - TWO * XNU))
      EMU   = E / (TWO * (ONE + XNU))
      TWOMU = TWO * EMU
!
!     Elastic trial stress (Voigt engineering shear).
!     OTIS seed initialization from GUI configuration
      DO OTI_HI = 1, 6
         DEV_TRIAL_OTI(OTI_HI) = 0.0D0
      END DO
      DGAMMA_OTI = 0.0D0
      DO OTI_HI = 1, NTENS
         DSTRAN_OTI(OTI_HI) = 0.0D0
      END DO
      EQPLAS_N_OTI = 0.0D0
      PHI_OTI = 0.0D0
      PTRIAL_OTI = 0.0D0
      Q_TRIAL_OTI = 0.0D0
      SCALE_OTI = 0.0D0
      SIGMA_Y_OTI = 0.0D0
      DO OTI_HI = 1, NSTATV
         STATEV_OTI(OTI_HI) = 0.0D0
      END DO
      DO OTI_HI = 1, NTENS
         STRESS_OTI(OTI_HI) = 0.0D0
      END DO
      DO OTI_HI = 1, 6
         STRESS_TRIAL_OTI(OTI_HI) = 0.0D0
      END DO
      DO OTI_I = 1, NTENS
         DSTRAN_OTI(OTI_I) = DSTRAN(OTI_I)
      END DO
      DO OTI_I = 1, NTENS
         STRESS_OTI(OTI_I) = STRESS(OTI_I)
      END DO
      DO OTI_I = 1, NSTATV
         STATEV_OTI(OTI_I) = STATEV(OTI_I)
      END DO
      DSTRAN_OTI(1) = DSTRAN_OTI(1) + OTI_E1
      DSTRAN_OTI(2) = DSTRAN_OTI(2) + OTI_E2
      DSTRAN_OTI(3) = DSTRAN_OTI(3) + OTI_E3
      DSTRAN_OTI(4) = DSTRAN_OTI(4) + OTI_E4
      DSTRAN_OTI(5) = DSTRAN_OTI(5) + OTI_E5
      DSTRAN_OTI(6) = DSTRAN_OTI(6) + OTI_E6
      STRESS_TRIAL_OTI(1) = STRESS_OTI(1) + (ELAM + TWOMU) * &
     & DSTRAN_OTI(1) + ELAM * DSTRAN_OTI(2) + ELAM * DSTRAN_OTI(3)
      STRESS_TRIAL_OTI(2) = STRESS_OTI(2) + ELAM * DSTRAN_OTI(1) + &
     & (ELAM + TWOMU) * DSTRAN_OTI(2) + ELAM * DSTRAN_OTI(3)
      STRESS_TRIAL_OTI(3) = STRESS_OTI(3) + ELAM * DSTRAN_OTI(1) + ELAM &
     & * DSTRAN_OTI(2) + (ELAM + TWOMU) * DSTRAN_OTI(3)
      STRESS_TRIAL_OTI(4) = STRESS_OTI(4) + EMU * DSTRAN_OTI(4)
      STRESS_TRIAL_OTI(5) = STRESS_OTI(5) + EMU * DSTRAN_OTI(5)
      STRESS_TRIAL_OTI(6) = STRESS_OTI(6) + EMU * DSTRAN_OTI(6)
!
!     Trial pressure and deviator.
      PTRIAL_OTI = (STRESS_TRIAL_OTI(1) + STRESS_TRIAL_OTI(2) + &
     & STRESS_TRIAL_OTI(3)) * ONE_THIRD
      DEV_TRIAL_OTI(1) = STRESS_TRIAL_OTI(1) - PTRIAL_OTI
      DEV_TRIAL_OTI(2) = STRESS_TRIAL_OTI(2) - PTRIAL_OTI
      DEV_TRIAL_OTI(3) = STRESS_TRIAL_OTI(3) - PTRIAL_OTI
      DEV_TRIAL_OTI(4) = STRESS_TRIAL_OTI(4)
      DEV_TRIAL_OTI(5) = STRESS_TRIAL_OTI(5)
      DEV_TRIAL_OTI(6) = STRESS_TRIAL_OTI(6)
!
!     von Mises equivalent q = sqrt(3/2 sum s_ii^2 + 3 sum s_ij^2)
      Q_TRIAL_OTI = SQRT((((MAX(REAL(THREE_HALVES * (DEV_TRIAL_OTI(1)* &
     & DEV_TRIAL_OTI(1) + DEV_TRIAL_OTI(2)*DEV_TRIAL_OTI(2) + &
     & DEV_TRIAL_OTI(3)*DEV_TRIAL_OTI(3)) + THREE * (DEV_TRIAL_OTI(4)* &
     & DEV_TRIAL_OTI(4) + DEV_TRIAL_OTI(5)*DEV_TRIAL_OTI(5) + &
     & DEV_TRIAL_OTI(6)*DEV_TRIAL_OTI(6))), 1.0D-30)) - &
     & REAL(THREE_HALVES * (DEV_TRIAL_OTI(1)*DEV_TRIAL_OTI(1) + &
     & DEV_TRIAL_OTI(2)*DEV_TRIAL_OTI(2) + DEV_TRIAL_OTI(3)* &
     & DEV_TRIAL_OTI(3)) + THREE * (DEV_TRIAL_OTI(4)*DEV_TRIAL_OTI(4) + &
     & DEV_TRIAL_OTI(5)*DEV_TRIAL_OTI(5) + DEV_TRIAL_OTI(6)* &
     & DEV_TRIAL_OTI(6)))) + (THREE_HALVES * (DEV_TRIAL_OTI(1)* &
     & DEV_TRIAL_OTI(1) + DEV_TRIAL_OTI(2)*DEV_TRIAL_OTI(2) + &
     & DEV_TRIAL_OTI(3)*DEV_TRIAL_OTI(3)) + THREE * (DEV_TRIAL_OTI(4)* &
     & DEV_TRIAL_OTI(4) + DEV_TRIAL_OTI(5)*DEV_TRIAL_OTI(5) + &
     & DEV_TRIAL_OTI(6)*DEV_TRIAL_OTI(6)))))
!    1                              + DEV_TRIAL(2)*DEV_TRIAL(2)
!    2                              + DEV_TRIAL(3)*DEV_TRIAL(3))
!     OTIS-SKIP: 3          + THREE * (DEV_TRIAL(4)*DEV_TRIAL(4)
!     OTIS-SKIP: 4                   + DEV_TRIAL(5)*DEV_TRIAL(5)
!     OTIS-SKIP: 5                   + DEV_TRIAL(6)*DEV_TRIAL(6)))
!
      EQPLAS_N_OTI = STATEV_OTI(1)
      SIGMA_Y_OTI = SIGY0 + H * EQPLAS_N_OTI
      PHI_OTI = Q_TRIAL_OTI - SIGMA_Y_OTI
!
      IF (REAL(PHI_OTI) .LE. ZERO) THEN
!        Elastic increment.
         DO I = 1, NTENS
            STRESS_OTI(I) = STRESS_TRIAL_OTI(I)
         END DO
      ELSE
!        Radial return.
         DGAMMA_OTI = PHI_OTI / (THREE * EMU + H)
         SCALE_OTI = THREE * EMU * DGAMMA_OTI / Q_TRIAL_OTI
      STRESS_OTI(1) = DEV_TRIAL_OTI(1) * (ONE - SCALE_OTI) + PTRIAL_OTI
      STRESS_OTI(2) = DEV_TRIAL_OTI(2) * (ONE - SCALE_OTI) + PTRIAL_OTI
      STRESS_OTI(3) = DEV_TRIAL_OTI(3) * (ONE - SCALE_OTI) + PTRIAL_OTI
         STRESS_OTI(4) = DEV_TRIAL_OTI(4) * (ONE - SCALE_OTI)
         STRESS_OTI(5) = DEV_TRIAL_OTI(5) * (ONE - SCALE_OTI)
         STRESS_OTI(6) = DEV_TRIAL_OTI(6) * (ONE - SCALE_OTI)
         STATEV_OTI(1) = EQPLAS_N_OTI + DGAMMA_OTI
      END IF
!
!     Consistent tangent — plain elastic form for now; the transformer
!     will not use this for parameter sensitivities.
!     OTIS-SKIP: DO I = 1, NTENS
!     OTIS-SKIP: DO J = 1, NTENS
!     OTIS-SKIP: DDSDDE(I, J) = ZERO
!     OTIS-SKIP: END DO
!     OTIS-SKIP: END DO
!     OTIS-SKIP: DO I = 1, 3
!     OTIS-SKIP: DO J = 1, 3
!     OTIS-SKIP: DDSDDE(I, J) = ELAM
!     OTIS-SKIP: END DO
!     OTIS-SKIP: DDSDDE(I, I) = ELAM + TWOMU
!     OTIS-SKIP: END DO
!     OTIS-SKIP: DDSDDE(4, 4) = EMU
!     OTIS-SKIP: DDSDDE(5, 5) = EMU
!     OTIS-SKIP: DDSDDE(6, 6) = EMU
!     Copy real-valued OTIS outputs back to Abaqus arrays
      DO OTI_I = 1, NTENS
         STRESS(OTI_I) = REAL(STRESS_OTI(OTI_I))
      END DO
      DO OTI_I = 1, NSTATV
         STATEV(OTI_I) = REAL(STATEV_OTI(OTI_I))
      END DO
!     OTIS DDSDDE extraction: DDSDDE(i,j) = d STRESS(i) / d DSTRAN(j)
      DO OTI_I = 1, NTENS
         DO OTI_J = 1, NTENS
            DDSDDE(OTI_I,OTI_J) = &
     & GETIM(STRESS_OTI(OTI_I),OTI_J)
         END DO
      END DO
!     OTIS higher-order stress Jacobians (orders 2..4) -> oti_hjac.dat
      CALL GETOUTDIR(OTI_OUTDIR, IOTILN)
      OPEN(NEWUNIT=IOTIHJ,FILE=OTI_OUTDIR(1:IOTILN)// &
     & '/oti_hjac.dat',POSITION='APPEND')
      WRITE(IOTIHJ,*)'#',NOEL,NPT,KSTEP,KINC
      DO OTI_I = 1, NTENS
         WRITE(IOTIHJ,*)OTI_I,2,1,1,GETIM(STRESS_OTI(OTI_I),7)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,2,1,2,GETIM(STRESS_OTI(OTI_I),8)
         WRITE(IOTIHJ,*)OTI_I,2,1,3,GETIM(STRESS_OTI(OTI_I),10)
         WRITE(IOTIHJ,*)OTI_I,2,1,4,GETIM(STRESS_OTI(OTI_I),13)
         WRITE(IOTIHJ,*)OTI_I,2,1,5,GETIM(STRESS_OTI(OTI_I),17)
         WRITE(IOTIHJ,*)OTI_I,2,1,6,GETIM(STRESS_OTI(OTI_I),22)
         WRITE(IOTIHJ,*)OTI_I,2,2,2,GETIM(STRESS_OTI(OTI_I),9)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,2,2,3,GETIM(STRESS_OTI(OTI_I),11)
         WRITE(IOTIHJ,*)OTI_I,2,2,4,GETIM(STRESS_OTI(OTI_I),14)
         WRITE(IOTIHJ,*)OTI_I,2,2,5,GETIM(STRESS_OTI(OTI_I),18)
         WRITE(IOTIHJ,*)OTI_I,2,2,6,GETIM(STRESS_OTI(OTI_I),23)
         WRITE(IOTIHJ,*)OTI_I,2,3,3,GETIM(STRESS_OTI(OTI_I),12)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,2,3,4,GETIM(STRESS_OTI(OTI_I),15)
         WRITE(IOTIHJ,*)OTI_I,2,3,5,GETIM(STRESS_OTI(OTI_I),19)
         WRITE(IOTIHJ,*)OTI_I,2,3,6,GETIM(STRESS_OTI(OTI_I),24)
         WRITE(IOTIHJ,*)OTI_I,2,4,4,GETIM(STRESS_OTI(OTI_I),16)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,2,4,5,GETIM(STRESS_OTI(OTI_I),20)
         WRITE(IOTIHJ,*)OTI_I,2,4,6,GETIM(STRESS_OTI(OTI_I),25)
         WRITE(IOTIHJ,*)OTI_I,2,5,5,GETIM(STRESS_OTI(OTI_I),21)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,2,5,6,GETIM(STRESS_OTI(OTI_I),26)
         WRITE(IOTIHJ,*)OTI_I,2,6,6,GETIM(STRESS_OTI(OTI_I),27)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,1,1,1,GETIM(STRESS_OTI(OTI_I),28)*6.0D0
         WRITE(IOTIHJ,*)OTI_I,3,1,1,2,GETIM(STRESS_OTI(OTI_I),29)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,1,1,3,GETIM(STRESS_OTI(OTI_I),32)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,1,1,4,GETIM(STRESS_OTI(OTI_I),38)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,1,1,5,GETIM(STRESS_OTI(OTI_I),48)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,1,1,6,GETIM(STRESS_OTI(OTI_I),63)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,1,2,2,GETIM(STRESS_OTI(OTI_I),30)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,1,2,3,GETIM(STRESS_OTI(OTI_I),33)
         WRITE(IOTIHJ,*)OTI_I,3,1,2,4,GETIM(STRESS_OTI(OTI_I),39)
         WRITE(IOTIHJ,*)OTI_I,3,1,2,5,GETIM(STRESS_OTI(OTI_I),49)
         WRITE(IOTIHJ,*)OTI_I,3,1,2,6,GETIM(STRESS_OTI(OTI_I),64)
         WRITE(IOTIHJ,*)OTI_I,3,1,3,3,GETIM(STRESS_OTI(OTI_I),34)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,1,3,4,GETIM(STRESS_OTI(OTI_I),40)
         WRITE(IOTIHJ,*)OTI_I,3,1,3,5,GETIM(STRESS_OTI(OTI_I),50)
         WRITE(IOTIHJ,*)OTI_I,3,1,3,6,GETIM(STRESS_OTI(OTI_I),65)
         WRITE(IOTIHJ,*)OTI_I,3,1,4,4,GETIM(STRESS_OTI(OTI_I),41)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,1,4,5,GETIM(STRESS_OTI(OTI_I),51)
         WRITE(IOTIHJ,*)OTI_I,3,1,4,6,GETIM(STRESS_OTI(OTI_I),66)
         WRITE(IOTIHJ,*)OTI_I,3,1,5,5,GETIM(STRESS_OTI(OTI_I),52)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,1,5,6,GETIM(STRESS_OTI(OTI_I),67)
         WRITE(IOTIHJ,*)OTI_I,3,1,6,6,GETIM(STRESS_OTI(OTI_I),68)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,2,2,2,GETIM(STRESS_OTI(OTI_I),31)*6.0D0
         WRITE(IOTIHJ,*)OTI_I,3,2,2,3,GETIM(STRESS_OTI(OTI_I),35)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,2,2,4,GETIM(STRESS_OTI(OTI_I),42)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,2,2,5,GETIM(STRESS_OTI(OTI_I),53)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,2,2,6,GETIM(STRESS_OTI(OTI_I),69)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,2,3,3,GETIM(STRESS_OTI(OTI_I),36)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,2,3,4,GETIM(STRESS_OTI(OTI_I),43)
         WRITE(IOTIHJ,*)OTI_I,3,2,3,5,GETIM(STRESS_OTI(OTI_I),54)
         WRITE(IOTIHJ,*)OTI_I,3,2,3,6,GETIM(STRESS_OTI(OTI_I),70)
         WRITE(IOTIHJ,*)OTI_I,3,2,4,4,GETIM(STRESS_OTI(OTI_I),44)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,2,4,5,GETIM(STRESS_OTI(OTI_I),55)
         WRITE(IOTIHJ,*)OTI_I,3,2,4,6,GETIM(STRESS_OTI(OTI_I),71)
         WRITE(IOTIHJ,*)OTI_I,3,2,5,5,GETIM(STRESS_OTI(OTI_I),56)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,2,5,6,GETIM(STRESS_OTI(OTI_I),72)
         WRITE(IOTIHJ,*)OTI_I,3,2,6,6,GETIM(STRESS_OTI(OTI_I),73)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,3,3,3,GETIM(STRESS_OTI(OTI_I),37)*6.0D0
         WRITE(IOTIHJ,*)OTI_I,3,3,3,4,GETIM(STRESS_OTI(OTI_I),45)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,3,3,5,GETIM(STRESS_OTI(OTI_I),57)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,3,3,6,GETIM(STRESS_OTI(OTI_I),74)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,3,4,4,GETIM(STRESS_OTI(OTI_I),46)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,3,4,5,GETIM(STRESS_OTI(OTI_I),58)
         WRITE(IOTIHJ,*)OTI_I,3,3,4,6,GETIM(STRESS_OTI(OTI_I),75)
         WRITE(IOTIHJ,*)OTI_I,3,3,5,5,GETIM(STRESS_OTI(OTI_I),59)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,3,5,6,GETIM(STRESS_OTI(OTI_I),76)
         WRITE(IOTIHJ,*)OTI_I,3,3,6,6,GETIM(STRESS_OTI(OTI_I),77)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,4,4,4,GETIM(STRESS_OTI(OTI_I),47)*6.0D0
         WRITE(IOTIHJ,*)OTI_I,3,4,4,5,GETIM(STRESS_OTI(OTI_I),60)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,4,4,6,GETIM(STRESS_OTI(OTI_I),78)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,4,5,5,GETIM(STRESS_OTI(OTI_I),61)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,4,5,6,GETIM(STRESS_OTI(OTI_I),79)
         WRITE(IOTIHJ,*)OTI_I,3,4,6,6,GETIM(STRESS_OTI(OTI_I),80)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,5,5,5,GETIM(STRESS_OTI(OTI_I),62)*6.0D0
         WRITE(IOTIHJ,*)OTI_I,3,5,5,6,GETIM(STRESS_OTI(OTI_I),81)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,5,6,6,GETIM(STRESS_OTI(OTI_I),82)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,3,6,6,6,GETIM(STRESS_OTI(OTI_I),83)*6.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,1,1,1,GETIM(STRESS_OTI(OTI_I),84)*24.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,1,1,2,GETIM(STRESS_OTI(OTI_I),85)*6.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,1,1,3,GETIM(STRESS_OTI(OTI_I),89)*6.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,1,1,4,GETIM(STRESS_OTI(OTI_I),99)*6.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,1,1,5,GETIM(STRESS_OTI(OTI_I),119)*6.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,1,1,6,GETIM(STRESS_OTI(OTI_I),154)*6.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,1,2,2,GETIM(STRESS_OTI(OTI_I),86)*4.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,1,2,3,GETIM(STRESS_OTI(OTI_I),90)*2.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,1,2,4,GETIM(STRESS_OTI(OTI_I),100)*2.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,1,2,5,GETIM(STRESS_OTI(OTI_I),120)*2.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,1,2,6,GETIM(STRESS_OTI(OTI_I),155)*2.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,1,3,3,GETIM(STRESS_OTI(OTI_I),91)*4.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,1,3,4,GETIM(STRESS_OTI(OTI_I),101)*2.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,1,3,5,GETIM(STRESS_OTI(OTI_I),121)*2.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,1,3,6,GETIM(STRESS_OTI(OTI_I),156)*2.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,1,4,4,GETIM(STRESS_OTI(OTI_I),102)*4.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,1,4,5,GETIM(STRESS_OTI(OTI_I),122)*2.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,1,4,6,GETIM(STRESS_OTI(OTI_I),157)*2.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,1,5,5,GETIM(STRESS_OTI(OTI_I),123)*4.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,1,5,6,GETIM(STRESS_OTI(OTI_I),158)*2.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,1,6,6,GETIM(STRESS_OTI(OTI_I),159)*4.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,2,2,2,GETIM(STRESS_OTI(OTI_I),87)*6.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,2,2,3,GETIM(STRESS_OTI(OTI_I),92)*2.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,2,2,4,GETIM(STRESS_OTI(OTI_I),103)*2.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,2,2,5,GETIM(STRESS_OTI(OTI_I),124)*2.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,2,2,6,GETIM(STRESS_OTI(OTI_I),160)*2.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,2,3,3,GETIM(STRESS_OTI(OTI_I),93)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,4,1,2,3,4,GETIM(STRESS_OTI(OTI_I),104)
         WRITE(IOTIHJ,*)OTI_I,4,1,2,3,5,GETIM(STRESS_OTI(OTI_I),125)
         WRITE(IOTIHJ,*)OTI_I,4,1,2,3,6,GETIM(STRESS_OTI(OTI_I),161)
      WRITE(IOTIHJ,*)OTI_I,4,1,2,4,4,GETIM(STRESS_OTI(OTI_I),105)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,4,1,2,4,5,GETIM(STRESS_OTI(OTI_I),126)
         WRITE(IOTIHJ,*)OTI_I,4,1,2,4,6,GETIM(STRESS_OTI(OTI_I),162)
      WRITE(IOTIHJ,*)OTI_I,4,1,2,5,5,GETIM(STRESS_OTI(OTI_I),127)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,4,1,2,5,6,GETIM(STRESS_OTI(OTI_I),163)
      WRITE(IOTIHJ,*)OTI_I,4,1,2,6,6,GETIM(STRESS_OTI(OTI_I),164)*2.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,3,3,3,GETIM(STRESS_OTI(OTI_I),94)*6.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,3,3,4,GETIM(STRESS_OTI(OTI_I),106)*2.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,3,3,5,GETIM(STRESS_OTI(OTI_I),128)*2.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,3,3,6,GETIM(STRESS_OTI(OTI_I),165)*2.0D0
      WRITE(IOTIHJ,*)OTI_I,4,1,3,4,4,GETIM(STRESS_OTI(OTI_I),107)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,4,1,3,4,5,GETIM(STRESS_OTI(OTI_I),129)
         WRITE(IOTIHJ,*)OTI_I,4,1,3,4,6,GETIM(STRESS_OTI(OTI_I),166)
      WRITE(IOTIHJ,*)OTI_I,4,1,3,5,5,GETIM(STRESS_OTI(OTI_I),130)*2.0D0
         WRITE(IOTIHJ,*)OTI_I,4,1,3,5,6,GETIM(STRESS_OTI(OTI_I),167)
